content.content:
1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file adds local lineage snapshots: a snapshot freezes one graph as a
4	// versioned, content-addressed JSON document, and two snapshots can be compared
5	// read-only. Every byte a snapshot writes is determined solely by the graph's
6	// semantics — dataset names and their direct upstreams — never by record
7	// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
8	// file path.
9	package chainledger
10	
11	import (
12		"bytes"
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"errors"
17		"fmt"
18		"sort"
19	)
20	
21	// SnapshotFormatVersion is the only on-disk snapshot format understood.
22	const SnapshotFormatVersion = 1
23	
24	// SnapshotFile is the on-disk representation of one frozen lineage graph.
25	//
26	// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
27	// verified against Graph on every read; Graph carries the complete graph.
28	type SnapshotFile struct {
29		FormatVersion int       `json:"formatVersion"`
30		ContentID     string    `json:"contentId"`
31		Graph         GraphFile `json:"graph"`
32	}
33	
34	// RootSourceChange reports that one dataset present in BOTH versions reaches a
35	// different set of root sources. OldRoots and NewRoots are sorted by name and
36	// never nil, so empty root sets encode as [] rather than null.
37	type RootSourceChange struct {
38		Dataset  string   `json:"dataset"`
39		OldRoots []string `json:"oldRoots"`
40		NewRoots []string `json:"newRoots"`
41	}
42	
43	// CompareReport is the deterministic, read-only diff of two snapshots read in
44	// the fixed direction old -> new.
45	//
46	// NewDatasets and RemovedDatasets list nodes present on only one side.
47	// ChangedDatasets lists datasets present on both sides whose direct upstream
48	// set actually changed. AddedRelations and RemovedRelations list every
49	// directed edge present on only one side, including edges that vanish because
50	// one endpoint node was removed. RootSourceChanges covers only datasets common
51	// to both versions whose reachable root set differs; added or removed datasets
52	// never appear there.
53	type CompareReport struct {
54		NewDatasets       []string           `json:"newDatasets"`
55		RemovedDatasets   []string           `json:"removedDatasets"`
56		ChangedDatasets   []string           `json:"changedDatasets"`
57		AddedRelations    []Relation         `json:"addedRelations"`
58		RemovedRelations  []Relation         `json:"removedRelations"`
59		RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
60	}
61	
62	// contentIDPrefix names the hash algorithm used for content addressing.
63	const contentIDPrefix = "sha256:"
64	
65	// graphAdjacencyFromFile builds the validated, normalized parent adjacency
66	// directly from a parsed graph file. It rejects empty names, duplicate
67	// datasets, and references to upstreams that are not declared; cycle checking
68	// is the caller's responsibility (via validateAcyclic) so the reported reason
69	// stays specific.
70	func graphAdjacencyFromFile(gf GraphFile) (adjacency, error) {
71		adj := make(adjacency, len(gf.Datasets))
72		for _, ds := range gf.Datasets {
73			if ds.Name == "" {
74				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
75			}
76			if _, exists := adj[ds.Name]; exists {
77				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
78			}
79			adj[ds.Name] = uniqueSorted(ds.Upstreams)
80		}
81		for name, parents := range adj {
82			for _, parent := range parents {
83				if _, ok := adj[parent]; !ok {
84					return nil, fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
85				}
86			}
87		}
88		return adj, nil
89	}
90	
91	// canonicalGraph serializes the graph's semantics deterministically: datasets
92	// sorted by name byte order with sorted, duplicate-free upstream lists, compact
93	// JSON with no insignificant whitespace. Two semantically equal graphs always
94	// produce identical bytes.
95	func canonicalGraph(adj adjacency) ([]byte, error) {
96		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
97		return json.Marshal(gf)
98	}
99	
100	// computeContentID returns the content identifier of the graph bytes:
101	// "sha256:" followed by the lowercase hex SHA-256 digest.
102	func computeContentID(canonical []byte) string {
103		sum := sha256.Sum256(canonical)
104		return contentIDPrefix + hex.EncodeToString(sum[:])
105	}
106	
107	// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
108	// version 1 and the matching content identifier. It does not mutate graph. The
109	// returned document and its serialized bytes depend only on graph semantics.
110	func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
111		if err := ValidateGraph(graph); err != nil {
112			return nil, err
113		}
114		adj, err := graphAdjacency(graph)
115		if err != nil {
116			return nil, err
117		}
118		canonical, err := canonicalGraph(adj)
119		if err != nil {
120			return nil, err
121		}
122		return &SnapshotFile{
123			FormatVersion: SnapshotFormatVersion,
124			ContentID:     computeContentID(canonical),
125			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
126		}, nil
127	}
128	
129	// MarshalSnapshot serializes a snapshot the same way for every save: indented
130	// JSON keyed by struct field order, terminated by a single newline.
131	func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
132		var buf bytes.Buffer
133		enc := json.NewEncoder(&buf)
134		enc.SetIndent("", "  ")
135		enc.SetEscapeHTML(false)
136		if err := enc.Encode(snap); err != nil {
137			return nil, err
138		}
139		return buf.Bytes(), nil
140	}
141	
142	// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
143	// can distinguish "field absent" from "field present with a zero value"
144	// (e.g. a missing formatVersion must be rejected rather than read as 0).
145	type rawSnapshot struct {
146		FormatVersion json.RawMessage `json:"formatVersion"`
147		ContentID     json.RawMessage `json:"contentId"`
148		Graph         json.RawMessage `json:"graph"`
149	}
150	
151	// isJSONNull reports whether a raw JSON value is the literal null.
152	func isJSONNull(raw json.RawMessage) bool {
153		return string(bytes.TrimSpace(raw)) == "null"
154	}
155	
156	// ParseSnapshot parses and strictly validates one snapshot document: required
157	// fields must be present and well-typed, no known field may be declared twice
158	// within the same object (even with identical values, a null first, or a
159	// spelling that merely differs in case or escapes), the format version must be
160	// supported, the embedded graph must be structurally valid (no empty names,
161	// duplicate datasets, missing upstreams, or cycles), and the content
162	// identifier must correspond exactly to the graph. A tampered, corrupt, or
163	// otherwise invalid snapshot is rejected, so a bad file can never be trusted
164	// as a version.
165	func ParseSnapshot(data []byte) (*SnapshotFile, error) {
166		if err := checkDuplicateFields(data); err != nil {
167			return nil, err
168		}
169		var raw rawSnapshot
170		if err := json.Unmarshal(data, &raw); err != nil {
171			return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
172		}
173		if len(raw.FormatVersion) == 0 {
174			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
175		}
176		if len(raw.ContentID) == 0 {
177			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
178		}
179		if len(raw.Graph) == 0 {
180			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
181		}
182		// An explicit JSON null is present-but-untyped and must not be silently
183		// treated as a zero value (in particular, graph:null must not read as an
184		// empty graph).
185		if isJSONNull(raw.FormatVersion) {
186			return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
187		}
188		if isJSONNull(raw.ContentID) {
189			return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
190		}
191		if isJSONNull(raw.Graph) {
192			return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
193		}
194	
195		var version int
196		if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
197			return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
198		}
199		if version != SnapshotFormatVersion {
200			return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
201		}
202	
203		var contentID string
204		if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
205			return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
206		}
207		if contentID == "" {
208			return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
209		}
210	
211		var gf GraphFile
212		if err := json.Unmarshal(raw.Graph, &gf); err != nil {
213			return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
214		}
215		adj, err := graphAdjacencyFromFile(gf)
216		if err != nil {
217			return nil, err
218		}
219		if err := validateAcyclic(adj); err != nil {
220			return nil, err
221		}
222	
223		canonical, err := canonicalGraph(adj)
224		if err != nil {
225			return nil, err
226		}
227		if want := computeContentID(canonical); contentID != want {
228			return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
229		}
230	
231		return &SnapshotFile{
232			FormatVersion: version,
233			ContentID:     contentID,
234			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
235		}, nil
236	}
237	
238	// errAbortScan stops the duplicate-field scan when the document is too
239	// malformed to keep walking; the regular parse then reports the syntax or
240	// type error instead.
241	var errAbortScan = errors.New("chainledger: abort duplicate field scan")
242	
243	// checkDuplicateFields rejects a snapshot in which a known field is declared
244	// more than once within the same object: formatVersion, contentId, and graph
245	// at the top level, datasets inside graph, and name and upstreams inside each
246	// dataset record. A repeated field is ambiguous — the reader would silently
247	// keep only one declaration — so the whole snapshot is refused even when the
248	// duplicates carry identical values, the first is null, or the surviving value
249	// would pass every other check.
250	//
251	// Field names are compared after JSON string unescaping and with the same
252	// ASCII case-folding the decoder applies, so "name", "name", and "Name"
253	// all collide. Unknown fields keep their ignore-everything behavior and may
254	// repeat freely. Documents that are not shaped like a snapshot at all are left
255	// to the regular parse, which reports the structural problem.
256	func checkDuplicateFields(data []byte) error {
257		dec := json.NewDecoder(bytes.NewReader(data))
258		err := checkTopLevelObject(dec)
259		if errors.Is(err, errAbortScan) {
260			return nil
261		}
262		return err
263	}
264	
265	// checkTopLevelObject scans the top-level snapshot object for repeated
266	// formatVersion/contentId/graph declarations, descending into graph values.
267	func checkTopLevelObject(dec *json.Decoder) error {
268		tok, err := scanToken(dec)
269		if err != nil {
270			return err
271		}
272		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
273			return nil // not an object: the regular parse reports the type error
274		}
275		seen := make(map[string]bool, 3)
276		for dec.More() {
277			key, err := scanKey(dec)
278			if err != nil {
279				return err
280			}
281			field, known := snapshotField(key)
282			if known {
283				if seen[field] {
284					return duplicateFieldError(field, "at the top level of the snapshot")
285				}
286				seen[field] = true
287			}
288			if field == "graph" {
289				if err := checkGraphValue(dec); err != nil {
290					return err
291				}
292			} else if err := skipValue(dec); err != nil {
293				return err
294			}
295		}
296		_, err = scanToken(dec) // closing '}'
297		return err
298	}
299	
300	// checkGraphValue scans one graph value for a repeated datasets declaration,
301	// descending into each dataset record of the datasets array.
302	func checkGraphValue(dec *json.Decoder) error {
303		tok, err := scanToken(dec)
304		if err != nil {
305			return err
306		}
307		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
308			// Not an object (null, array, scalar): consume any remainder and let
309			// the regular parse report the type problem.
310			return skipRest(dec, tok)
311		}
312		seen := false
313		for dec.More() {
314			key, err := scanKey(dec)
315			if err != nil {
316				return err
317			}
318			if asciiFoldEqual(key, "datasets") {
319				if seen {
320					return duplicateFieldError("datasets", `in "graph"`)
321				}
322				seen = true
323				if err := checkDatasetsValue(dec); err != nil {
324					return err
325				}
326			} else if err := skipValue(dec); err != nil {
327				return err
328			}
329		}
330		_, err = scanToken(dec) // closing '}'
331		return err
332	}
333	
334	// checkDatasetsValue scans one datasets array, checking every record that is
335	// an object for repeated name/upstreams declarations.
336	func checkDatasetsValue(dec *json.Decoder) error {
337		tok, err := scanToken(dec)
338		if err != nil {
339			return err
340		}
341		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
342			return skipRest(dec, tok) // not an array: the regular parse reports it
343		}
344		for index := 0; dec.More(); index++ {
345			if err := checkDatasetRecord(dec, index); err != nil {
346				return err
347			}
348		}
349		_, err = scanToken(dec) // closing ']'
350		return err
351	}
352	
353	// checkDatasetRecord scans one element of the datasets array. If it is an
354	// object, name and upstreams must each be declared at most once.
355	func checkDatasetRecord(dec *json.Decoder, index int) error {
356		tok, err := scanToken(dec)
357		if err != nil {
358			return err
359		}
360		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
361			return skipRest(dec, tok) // not an object: the regular parse reports it
362		}
363		seen := make(map[string]bool, 2)
364		for dec.More() {
365			key, err := scanKey(dec)
366			if err != nil {
367				return err
368			}
369			if field, known := datasetField(key); known {
370				if seen[field] {
371					return duplicateFieldError(field, fmt.Sprintf("in the dataset record at index %d of \"datasets\"", index))
372				}
373				seen[field] = true
374			}
375			if err := skipValue(dec); err != nil {
376				return err
377			}
378		}
379		_, err = scanToken(dec) // closing '}'
380		return err
381	}
382	
383	// duplicateFieldError reports a known field declared twice, naming the field
384	// and where in the document the repetition occurred.
385	func duplicateFieldError(field, location string) error {
386		return fmt.Errorf("%w: field %q is declared more than once %s", ErrInvalidArgument, field, location)
387	}
388	
389	// snapshotField maps a top-level key to the canonical name of the snapshot
390	// field it selects, matching the decoder's case-insensitive field lookup.
391	func snapshotField(key string) (string, bool) {
392		switch {
393		case asciiFoldEqual(key, "formatVersion"):
394			return "formatVersion", true
395		case asciiFoldEqual(key, "contentId"):
396			return "contentId", true
397		case asciiFoldEqual(key, "graph"):
398			return "graph", true
399		}
400		return "", false
401	}
402	
403	// datasetField maps a dataset-record key to the canonical name of the record
404	// field it selects, matching the decoder's case-insensitive field lookup.
405	func datasetField(key string) (string, bool) {
406		switch {
407		case asciiFoldEqual(key, "name"):
408			return "name", true
409		case asciiFoldEqual(key, "upstreams"):
410			return "upstreams", true
411		}
412		return "", false
413	}
414	
415	// asciiFoldEqual reports whether a and b are equal under ASCII case folding,
416	// the same rule encoding/json uses when matching object keys to struct fields.
417	func asciiFoldEqual(a, b string) bool {
418		if len(a) != len(b) {
419			return false
420		}
421		for i := 0; i < len(a); i++ {
422			ca, cb := a[i], b[i]
423			if 'A' <= ca && ca <= 'Z' {
424				ca += 'a' - 'A'
425			}
426			if 'A' <= cb && cb <= 'Z' {
427				cb += 'a' - 'A'
428			}
429			if ca != cb {
430				return false
431			}
432		}
433		return true
434	}
435	
436	// scanToken reads one token; any decode failure aborts the scan so the
437	// regular parse can report the malformed document.
438	func scanToken(dec *json.Decoder) (json.Token, error) {
439		tok, err := dec.Token()
440		if err != nil {
441			return nil, errAbortScan
442		}
443		return tok, nil
444	}
445	
446	// scanKey reads the next key of the object currently being walked.
447	func scanKey(dec *json.Decoder) (string, error) {
448		tok, err := scanToken(dec)
449		if err != nil {
450			return "", err
451		}
452		key, ok := tok.(string)
453		if !ok {
454			return "", errAbortScan
455		}
456		return key, nil
457	}
458	
459	// skipValue consumes one complete JSON value.
460	func skipValue(dec *json.Decoder) error {
461		tok, err := scanToken(dec)
462		if err != nil {
463			return err
464		}
465		return skipRest(dec, tok)
466	}
467	
468	// skipRest consumes the remainder of a value whose first token is tok.
469	func skipRest(dec *json.Decoder, tok json.Token) error {
470		delim, ok := tok.(json.Delim)
471		if !ok {
472			return nil // scalar, fully consumed already
473		}
474		var closer json.Delim
475		switch delim {
476		case '{':
477			closer = '}'
478			for dec.More() {
479				if _, err := scanKey(dec); err != nil {
480					return err
481				}
482				if err := skipValue(dec); err != nil {
483					return err
484				}
485			}
486		case '[':
487			closer = ']'
488			for dec.More() {
489				if err := skipValue(dec); err != nil {
490					return err
491				}
492			}
493		default:
494			return errAbortScan
495		}
496		tok, err := scanToken(dec)
497		if err != nil {
498			return err
499		}
500		if end, ok := tok.(json.Delim); !ok || end != closer {
501			return errAbortScan
502		}
503		return nil
504	}
505	
506	// CompareSnapshots returns the fixed-direction diff from old to new. Both
507	// inputs are assumed to have passed ParseSnapshot; the report is fully
508	// deterministic and identical for semantically identical comparisons.
509	func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
510		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
511		newAdj := adjacencyFromValidFile(newSnap.Graph)
512	
513		added, removed := diffRelations(oldAdj, newAdj)
514	
515		var newNodes, removedNodes, changedNodes []string
516		for name := range newAdj {
517			if oldParents, ok := oldAdj[name]; !ok {
518				newNodes = append(newNodes, name)
519			} else if !stringSliceEqual(oldParents, newAdj[name]) {
520				changedNodes = append(changedNodes, name)
521			}
522		}
523		for name := range oldAdj {
524			if _, ok := newAdj[name]; !ok {
525				removedNodes = append(removedNodes, name)
526			}
527		}
528		sort.Strings(newNodes)
529		sort.Strings(removedNodes)
530		sort.Strings(changedNodes)
531	
532		common := make([]string, 0)
533		for name := range oldAdj {
534			if _, ok := newAdj[name]; ok {
535				common = append(common, name)
536			}
537		}
538		sort.Strings(common)
539	
540		rootChanges := make([]RootSourceChange, 0)
541		for _, name := range common {
542			oldRoots := rootSources(name, oldAdj)
543			newRoots := rootSources(name, newAdj)
544			if !stringSliceEqual(oldRoots, newRoots) {
545				rootChanges = append(rootChanges, RootSourceChange{
546					Dataset:  name,
547					OldRoots: oldRoots,
548					NewRoots: newRoots,
549				})
550			}
551		}
552	
553		return &CompareReport{
554			NewDatasets:       orEmptyStrings(newNodes),
555			RemovedDatasets:   orEmptyStrings(removedNodes),
556			ChangedDatasets:   orEmptyStrings(changedNodes),
557			AddedRelations:    orEmptyRelations(added),
558			RemovedRelations:  orEmptyRelations(removed),
559			RootSourceChanges: rootChanges,
560		}
561	}
562	
563	// adjacencyFromValidFile builds normalized parent adjacency from an already
564	// validated graph file.
565	func adjacencyFromValidFile(gf GraphFile) adjacency {
566		adj := make(adjacency, len(gf.Datasets))
567		for _, ds := range gf.Datasets {
568			adj[ds.Name] = uniqueSorted(ds.Upstreams)
569		}
570		return adj
571	}
572	
573	// rootSources returns the root datasets reachable from node by following
574	// direct upstream edges. A node without upstreams is itself a root and its own
575	// source, so it is included. Nodes reached by more than one path count once.
576	// The result is sorted by name and never nil.
577	func rootSources(node string, adj adjacency) []string {
578		visited := make(map[string]bool)
579		var roots []string
580		var walk func(string)
581		walk = func(current string) {
582			if visited[current] {
583				return
584			}
585			visited[current] = true
586			parents := adj[current]
587			if len(parents) == 0 {
588				roots = append(roots, current)
589				return
590			}
591			for _, parent := range parents {
592				walk(parent)
593			}
594		}
595		walk(node)
596		sort.Strings(roots)
597		return orEmptyStrings(roots)
598	}
599	
600	func orEmptyStrings(s []string) []string {
601		if s == nil {
602			return []string{}
603		}
604		return s
605	}
606	
607	func orEmptyRelations(r []Relation) []Relation {
608		if r == nil {
609			return []Relation{}
610		}
611		return r
612	}
613

